"""Write the parent's four analytical records, with counts taken from this run's ID logs."""
from pathlib import Path
import re
import yaml

run=Path(__file__).resolve().parents[1]
md=Path("theory.md").read_text()
exposure="Prior conversation included earlier judgements; no previous verification directory was opened in this run."
def record(k,statement,dependencies,steps,assessment,own=(),limits=()):
    text=md.split("\n### "+k+"\n",1)[1].split("\n### ",1)[0]
    hyp=re.findall(r'\b[AI]\d+\b',text.split("**Hypotheses:**",1)[1].splitlines()[0])
    report=(run/'logs'/('report_'+k+'.md')).read_text()
    direct,support=re.search(r'^\| \['+k+r'\]\(#[^)]*\) \| (.*?) \| (.*?) \|$',report,re.M).groups()
    rec=dict(id=k,run_id=run.name,auditor=dict(model="gpt-6",harness="Codex",date="2026-11-22",prior_exposure=exposure),
        verdict="sound",paper_statement="holds_as_printed",confidence="high",restatement=statement,
        differences_checked=[],hypotheses_used=hyp,unstated_hypotheses=[],relies_on=dependencies,
        steps=[dict(id=i,locator=l,claim=c,status="verified",method=m,note="Auditor's derivation. "+details) for i,(l,c,m,details) in enumerate(steps,1)],
        findings=[],numerical=dict(command=f"python numerics/run.py -k {k} --report verification/{run.name}/logs/report_{k}.md",
        direct=direct+" passed",supporting=support+" passed",assessment=assessment,own_checks=list(own)),not_checked=list(limits))
    (run/'proofs'/(k+'.yaml')).write_text(yaml.safe_dump(rec,sort_keys=False,allow_unicode=True,width=105))

def p2():
    record("P2","For each admissible exogenous market and every gamma>0 on the full closed theta interval, B's N order is nonincreasing and the 0 and S orders are constant in theta; at every theta the strict ordering is 0<N<S. For each fixed theta<1, holding the other market inputs fixed, the S-minus-N order gap first rises, then falls with gamma.",
    ["L1/L2 order solution; L3 own and cross continuation tail equations; P1 proof (A.18)–(A.19)."],
    [("P2(a), (A.18)–(A.19)","Direction of the N derivative and constancy of the other orders.","re-derivation","Use u=pA1,v=pB1,C=cA,B=cB,k=alphaA2*(pA2-C),n=alphaB2*(pB2-B),m=pB2-B. The N tail is qA+H/[v+(1-theta)n*gamma] with qA=C/(u+k*gamma), H=B-(v+n*gamma)*qA. A11 gives Bu>=Cv and Bk>=Cn, with strictness in their relevant weighted combination because either second-period shares differ, or equal second-period prices and unequal costs give strictly ordered margins per unit cost. Thus H>0. The tail increases and the uniform quantile order falls. The S and benchmark B tails contain no theta."),
     ("(A.20)","Both inequalities between B's three orders are strict.","re-derivation","The N tail lies between its endpoint values. At theta=0 it is B/(v+n*gamma)>B/(v+m*gamma) since 0<n<m. At theta=1 it is [B-n*gamma*qA]/v<B/v. Since 2*sigma*alphaB1>0, each strict tail comparison reverses for orders; endpoints and binding price ratios are included."),
     ("P2(c), quartic coefficient signs","There is at most one positive derivative root for every fixed theta<1.","symbolic","Apart from the positive scale, the gap equals gamma*(L+M*gamma)/D with D=(u+k*gamma)(v+(1-theta)*n*gamma)(v+m*gamma). L=Bu(m-n)+theta*n*(Bu-Cv)>0. M=(1-theta)*Bk*(m-n)+theta*m*(Bk-Cn)>0. Writing D as d0+d1*g+d2*g²+d3*g³, all four coefficients are positive; the derivative numerator has ascending coefficients Ld0,2Md0,Md1-Ld2,-2Ld3,-Md3. There is one sign change whatever the middle coefficient. scripts/P2_positive_root.py verifies the identities in symbols."),
     ("interior maximum gives a positive root","Existence of the crossing and both directions of monotonicity.","re-derivation","For fixed theta<1 the gap is positive by (b) and tends to zero at both ends of (0,infinity), as also follows from its positive linear/quadratic numerator and cubic denominator. Continuity puts a positive maximum in the interior. Equivalently, the derivative numerator is positive at zero and eventually negative. Together with Descartes this gives exactly one positive stationary point and the asserted order of signs. Theta=1 is outside part (c) and is covered by (a,b).")],
    "Exact grids scan theta, including 0 and 1 and binding A11, compare strict order levels, and examine the direction in gamma for fixed theta<1. Fixed-order sign comparisons and the derivative-root certificate establish different parts; a finite grid alone could miss a turning point.",["scripts/P2_positive_root.py; logs/P2_positive_root.log"])

def p7():
    record("P7","For either firm, scenario and every fixed feasible first-period sales state, all gamma>0 and every fixed other second-period price, the own-price curve on the price interval is nonincreasing or has one or two interior local maxima. As the rival price varies, the curve is nondecreasing or first nonincreasing and then nondecreasing.",
    ["LA1/LA2 joint proof: conditional second-period stock translation holds at all given prices and all gamma, independently of the large-gamma price-equilibrium conclusion.","L1 proof in each of the two possible orders of critical ratios."],
    [("conditional orders","A shift in S and a tilt in N.","re-derivation","Conditional Z adds to the inventory solution in either critical-ratio order; the S sales increment is constant, and the N share increment contributes -beta*gamma*R or +beta*gamma*R to the own or rival derivative. This holds even at zero sales."),
     ("(a), two own-price pieces","Both branch derivatives decrease with the own price.","re-derivation","Rescale prices and costs by 2*beta and demand by mu, so 2*beta=mu=1 in the following derivative bounds; write s=sigma/mu,U=upper,r=other,x=own. For the lower critical ratio, the derivative is -beta*(1+s)+c_i*s*(1+r)/x². For the higher it is -beta*(1+s)+c_i*s*(1+theta+(1-theta)*r)/x²+2*beta*c_j*theta*s/r. Each varies as a positive multiple of x^-2 plus a constant; both stock formulas agree at x=c_i*r/c_j."),
     ("(a), displayed negative upper-end bound","At the upper price the own-price derivative is strictly negative on either branch.","re-derivation","Write D=U-1. A13 implies D>(1+s)(c_A+2*c_B)/3 and A12 puts every feasible price above D. In units of beta*s the positive adjustment at x=U is affine in theta on the high branch. At theta=0 it is bounded by 2*c_i*(1+U)/U²<=2*c_i/D; this covers the low branch too. At theta=1 it is bounded by 4*c_i/U²+2*c_j/r<=(c_i+2*c_j)/D using U²>=4D. Both are bounded by 3/(1+s). Thus the derivative is at most -beta*(1-s+s²)/(1+s) in normalized units, including either assignment of firms; subtracting the N tilt preserves negativity."),
     ("(a), joining the pieces","Own-price shape has at most two interior maxima.","re-derivation","The slope is decreasing on each of at most two pieces. At the tie the added spillover term is theta*alpha_j*(z_i-z_j), which is zero there and has nonnegative right slope in the own price. No additional downward slope jump creates a third peak. The final slope is negative. Any positive-slope segment therefore has a following interior maximum, and there can be at most two."),
     ("(b), both rival-price pieces and the upper bound","Rival-price slope can turn from negative to positive at most once, and ends positive.","re-derivation","With r now the varying rival price, on the high-own-ratio piece the derivative is beta*(1+s-2*c_i*(1-theta)*s/x)-c_j*theta*s*(1+x)/r², increasing in r. On the other piece it is beta*(1+s-2*c_i*s/x)>0 since x>c_i and s<1. At r=U the adverse adjustment in units of beta*s is at most 2*c_i/D when theta=0 and 2*c_j*(1+U)/U²<=2*c_j/D when theta=1. Both are <=3/(1+s), giving the stated positive bound for either retailer in original units. The N tilt is positive; the same alternatives hold if the ratio tie is outside the interval or theta=0 or 1.")],
    "The two direct checks classify 16,000 own and 16,000 rival curves on 1,501-price grids, varying the market, rival price, theta and feasible prior-sales state. Supporting checks apply Nash-gap tests in both fractile branches. The sign proof covers kinks and peaks narrower than those grids.",["scripts/shared_price_derivatives.py; logs/price_derivatives.log"])

def p8():
    record("P8","On the whole price box and for sufficiently large gamma, both S orders fall weakly in own price and rise weakly in rival price, and in N, A's order falls and B's rises with A's price. Under (A.22) there exist an interior price neighborhood U and positive ell and finite gamma threshold common on U such that, whenever 0<=gamma*(1-theta)<=ell and gamma exceeds it, A's N order decreases and B's increases with B's price. For each fixed theta<1 the directions reverse on the box for sufficiently large gamma (depending on theta).",
    ["LA1 closed form and LA2 joint proof: uniform C² price control of the inventory approximation in (A.21), stronger than just the displayed value approximation of LA2."],
    [("P8(a)","Signs of the four S derivatives.","re-derivation","Differentiate the S order formula with the upper continuation price fixed. The critical points equal upper seed demand h=mu+sigma plus O(gamma^-1), with their own-price derivatives O(gamma^-2) uniformly. Since share slopes are +/-beta, the limiting slopes are +/-beta*h, strictly separated from zero on the compact box, including theta endpoints."),
     ("P8(b1)","Uniform signs with respect to A's price in N.","re-derivation","In LA2 the B denominator pB1+(1-theta)*gamma*nuB is bounded below by the lower price. Differentiating the numerator correction in pA1 contributes only O(gamma^-1), uniformly even at theta=1. The leading slopes are beta*zB for B and -beta*((1-theta)*zA+theta*zB) for A. Both z's are bounded below by mu-sigma>0; thus a common gamma suffices."),
     ("(A.22)–(A.24)","The condition selects an actual interior rectangle and a positive ell.","re-derivation","Put K=cB-cA*nuB/nuA>0, by the second-period limit margins and share ordering. The RHS of pB1²<sigma*K*(1+2*beta*pA1)/(beta*h) is strictly increasing in pA1. Its supremum at upper exceeds lower² exactly under A.22. Strict slack lets one choose an interior center, then a closed rectangle around it and ell>0 small enough to retain slack with the worst endpoints and ell*nuB. Equality in A.22 imposes no such conclusion."),
     ("(A.25)","Order and aggregate-order expansions are uniform in the specified regime.","re-derivation","For L=gamma*(1-theta)<=ell, theta*gamma*nuB*cA/(pA1+gamma*nuA)=cA*nuB/nuA+O_C1(gamma^-1) and the B denominator is >=lower. Summing orders gives zA+(1-theta)*alphaB*(zB-zA) up to the LA2 remainder. Its own C1 distance to h is O(gamma^-1), also at L=0."),
     ("(A.26) and the uniform bound","The B-price derivative is positive for B and negative for A in the rectangle.","re-derivation","At fixed L, differentiate alphaB*(h-2*sigma*K/(pB1+L*nuB)); the derivative is -beta*h+sigma*K*(1+2*beta*pA1+2*beta*L*nuB)/(pB1+L*nuB)^2. The positive slack in A.24 bounds it below uniformly at the worst corner. Subtract from the aggregate slope O(gamma^-1) to obtain A's negative slope using the same common threshold."),
     ("Finally, for any fixed theta<1","Opposite B-price signs at fixed theta.","re-derivation","With 1-theta fixed positive both critical tails are O_C1(gamma^-1) in the price arguments. LA2 then gives y_i=alpha_i*h+O_C1(gamma^-1). B's own slope tends to -beta*h and A's rival slope to +beta*h. The constant can diverge as theta tends to 1, consistent with the quantifiers.")],
    "Checks distinguish the fixed-theta grid from markets satisfying A.22 and prices inside A.23. The local test varies gamma at fixed markets and uses both theta=1 and a scaled near-one path; the other test holds theta<1 fixed. Finite differences in independently solved inventory games probe the strict leading signs and exclude rounded zeros.",["scripts/shared_price_derivatives.py; logs/price_derivatives.log"])

def p9():
    record("P9","For every admissible continuous-price market and each fixed theta in [0,1), a finite gamma threshold exists after which both two-period games admit the stated price/inventory equilibrium. For both retailers, prices in S start at the lower and end at the upper bound; in N each second-period price at an induced sales state lies strictly above the lower bound and below its own interior first-period price.",
    ["LA1's uniform S best replies and conditional orders; LA2 joint proof, price-smooth profit expansion for each fixed theta<1, and the stock/sales lower bound for induced states."],
    [("Scenario S, total payoff and derivative","Each retailer's first-period best response is its lower bound.","re-derivation","At the continuation price upper, value is pi0_i+(upper-ci)*gamma*R_i1. The equilibrium S tails are O_C1(1/gamma); uniform-demand lost-sales expectations are quadratic in them. Thus E R_i1=alpha_i*mu+O_C1(gamma^-2), and stocks/prices have bounded C1 norms. Differentiating the exact payoff gives -gamma*(upper-ci)*beta*mu+O(1), uniformly negative. The lower bound dominates and the two unique upper continuation prices at induced positive sales yield the stated strict path."),
     ("Scenario N, derivatives of reduced profit","Own curvature is strictly negative and cross derivative bounded.","re-derivation","For fixed theta<1 use the joint proof's expansion with C² control. Price-independent gamma*nu_i*mu+K_i drops out. Differentiating alpha_i*(mu*p_i-ci*(mu+sigma)) gives the displayed affine marginal and the Hessian entries -2*beta*mu and beta*mu, with O(gamma^-1) remainders uniform in the entire price box."),
     ("constrained price best responses","Existence and uniqueness in the reduced game, including price bounds.","re-derivation","A payoff with own derivative decreasing at rate m>=2*beta*mu-C/g and cross slope bounded by L<=beta*mu+C/g has a unique constrained maximizer whose change is bounded by L/m times the rival's change. This follows by adding the two one-dimensional optimality inequalities and is valid at endpoints. The reply map therefore contracts in the sup norm. Expected payoff against a rival distribution retains strict own concavity, giving a single pure reply and excluding a nondegenerate mixed equilibrium of the reduced game."),
     ("limiting interior equilibrium","Both limiting price pairs are interior and close to actual prices.","re-derivation","Solve 2*pi-pj=1/(2*beta)+(1+sigma/mu)*ci for the first-period game. This gives 1/(2*beta)+(1+sigma/mu)*(2ci+cj)/3. The second-period limits have factor 1 in the cost term. A13 puts the smallest second-period limit above the floor and largest first-period limit below the ceiling. Uniform payoff convergence and compactness force all accumulation points to be the unique interior limiting pair. The inverse of the limiting FOC matrix beta*mu*[[-2,1],[1,-2]] maps the uniform O(1/gamma) residual to O(1/gamma) deviations."),
     ("final strict price ordering","The positive limiting separation persists on every induced path.","re-derivation","For either firm the period-1 minus period-2 limit equals sigma*(2ci+cj)/(3*mu)>0. LA2 gives uniform second-period convergence on induced total sales bounded away from zero. Use half the minimum of the price margins and this separation to choose a common gamma for both firms and all induced states. The threshold may depend on theta; theta=1 is excluded.")],
    "The S check varies gamma and checks price corners after verifying inventory replies over a price grid. The N check uses five fixed markets below theta=1, searches two starts, checks the residual and deviations and tests strict period-by-period inequalities at representative realized sales. Distances to limiting prices are reported as diagnostics; the analytic argument establishes all induced states.")
if __name__=="__main__":
    import sys
    for key in (sys.argv[1:] or ["p2","p7","p8","p9"]):
        globals()[key.lower()]()
